CREATE TABLE schools (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, code VARCHAR(40) NOT NULL UNIQUE, email VARCHAR(160), phone VARCHAR(40), address VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NULL, username VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, role VARCHAR(40) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_user_school FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE students (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, admission_no VARCHAR(80) NOT NULL, full_name VARCHAR(160) NOT NULL, class_name VARCHAR(80), section VARCHAR(40), roll_no VARCHAR(40), gender VARCHAR(30), dob DATE, parent_name VARCHAR(160), parent_phone VARCHAR(40), photo_url VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_student_admission (school_id,admission_no), CONSTRAINT fk_student_school FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE teachers (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, employee_no VARCHAR(80) NOT NULL, full_name VARCHAR(160) NOT NULL, subject VARCHAR(120), phone VARCHAR(40), email VARCHAR(160), salary DECIMAL(12,2) DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_teacher_emp (school_id,employee_no), CONSTRAINT fk_teacher_school FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE refresh_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, token_hash VARCHAR(255) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_refresh_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE otp_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, otp_hash VARCHAR(255) NOT NULL, expires_at TIMESTAMP NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_otp_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NULL, user_id BIGINT NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(120), entity_id VARCHAR(80), ip_address VARCHAR(80), details TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_school (school_id,created_at));
CREATE TABLE module_records (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, module VARCHAR(80) NOT NULL, record_key VARCHAR(120), data_json JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL, active BOOLEAN NOT NULL DEFAULT TRUE, INDEX idx_module_school (school_id,module), CONSTRAINT fk_module_school FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE fee_payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, student_id BIGINT, receipt_no VARCHAR(100) NOT NULL, amount DECIMAL(12,2) NOT NULL, fee_head VARCHAR(120), status VARCHAR(30) NOT NULL, provider VARCHAR(40), provider_payment_id VARCHAR(160), paid_on DATE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_receipt (school_id,receipt_no), CONSTRAINT fk_fee_school FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE subscriptions (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, plan_code VARCHAR(60) NOT NULL, status VARCHAR(30) NOT NULL, billing_cycle VARCHAR(20) NOT NULL, amount DECIMAL(12,2) NOT NULL, starts_at TIMESTAMP NOT NULL, ends_at TIMESTAMP NULL, provider_subscription_id VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_sub_school FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE payment_orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, order_no VARCHAR(120) NOT NULL UNIQUE, amount DECIMAL(12,2) NOT NULL, currency VARCHAR(10) NOT NULL, status VARCHAR(30) NOT NULL, provider VARCHAR(40), provider_order_id VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_order_school FOREIGN KEY (school_id) REFERENCES schools(id));
